function mount(selector){root=document.querySelector(selector||'[data-a11y-root]');if(!root||root.getAttribute('data-a11y-mounted')==='true')return false;if(!bind())return false;state=sanitize(load());apply(state);root.removeAttribute('hidden');root.setAttribute('data-a11y-mounted','true');refresh();return true;}
window.A11yPrefs={version:VERSION,mount:mount,get:function(){return copy(state||sanitize(load()));},set:set,reset:reset,open:openPanel,close:closePanel,subscribe:function(fn){if(typeof fn!=='function')return function(){};listeners.push(fn);return function(){var i=listeners.indexOf(fn);if(i>=0)listeners.splice(i,1);};}};function boot(){mount();}
